import{_ as e,o as n,c as i,a2 as o}from"./chunks/framework.CDpkVv68.js";const u=JSON.parse('{"title":"Armas y familias de daño","description":"","frontmatter":{},"headers":[],"relativePath":"es/game-design/combat/weapons-and-damage.md","filePath":"es/game-design/combat/weapons-and-damage.md"}'),t={name:"es/game-design/combat/weapons-and-damage.md"};function s(r,a,d,c,l,m){return n(),i("div",null,[...a[0]||(a[0]=[o('<h1 id="weapons-and-damage-families" tabindex="-1">Armas y familias de daño <a class="header-anchor" href="#weapons-and-damage-families" aria-label="Enlace permanente a &quot;Armas y familias de daño&quot;">​</a></h1><p><strong>Estado del diseño: Propuesto para identidades de armas e interacciones ampliadas de lesiones; la separación global/local con estado Aceptado no cambia. Implementación: esta integración no establece mecánicas nuevas de familias de armas.</strong></p><p><a href="/Syrolands-Public/es/guide/combat/weapons-and-damage.html">Guía del jugador</a> · <a href="/Syrolands-Public/es/game-design/combat/overview.html">Fundamentos de combate</a></p><h2 id="behavior-before-damage-totals" tabindex="-1">Comportamiento antes que totales de daño <a class="header-anchor" href="#behavior-before-damage-totals" aria-label="Enlace permanente a &quot;Comportamiento antes que totales de daño&quot;">​</a></h2><p>El diseño del arma determina el problema táctico que presenta un ataque. La calidad de fabricación determina con qué eficiencia y consistencia funciona ese diseño. Corte/tajo, perforación/punción y contundencia/impacto son familias candidatas de lesión física, no una enumeración nueva de daño implementada ni una tabla de conversión de tipos de daño heredados. Un arma puede admitir más de un tipo de ataque; importa el ataque que se intenta además del objeto.</p><table tabindex="0"><thead><tr><th>Arma</th><th>Identidad con estado Propuesto</th><th>Preguntas abiertas</th></tr></thead><tbody><tr><td>Daga</td><td>Punción precisa y oportunidades breves, impacto bruto bajo</td><td>Alcance y protección contra ataques precisos repetidos</td></tr><tr><td>Espada</td><td>Capacidad versátil de corte y estocada</td><td>Selección de ataque, compromiso y recuperación</td></tr><tr><td>Martillo de guerra / maza</td><td>Impacto contundente, potencial de deformación y fractura; fallos costosos</td><td>Trauma transmitido por armadura y costes de control</td></tr><tr><td>Lanza</td><td>Estocada, penetración, alcance y control posicional</td><td>Restricciones de corta distancia e interacción con armadura</td></tr><tr><td>Hacha</td><td>Corte e impacto estructural con alto compromiso</td><td>Daño de equipo frente a lesión corporal</td></tr></tbody></table><p>Son direcciones, no heridas garantizadas ni equilibrio definitivo. Más daño por segundo no es el único eje de progresión. Las armas de una mano con escudo y las de dos manos deberían plantear decisiones diferentes. La <a href="/Syrolands-Public/es/game-design/combat/future-directions.html">propagación acotada de impacto</a> sigue siendo trabajo separado con estado Propuesto; un objeto de dos manos no recibe automáticamente cleave ni impactos completos adicionales.</p><h2 id="injury-and-mitigation-boundary" tabindex="-1">Límite de lesiones y mitigación <a class="header-anchor" href="#injury-and-mitigation-boundary" aria-label="Enlace permanente a &quot;Límite de lesiones y mitigación&quot;">​</a></h2><p>La región primaria real recibe la <a href="/Syrolands-Public/es/game-design/combat/damage.html">política de Local Trauma</a> experimental aceptada. El corte no instala actualmente sangrado, la perforación no ignora armadura por definición y el impacto contundente no instala fracturas. Los futuros cálculos de lesiones o armadura específicos por familia deben reconciliarse con esa política antes de implementar. Los ataques a cuello/cabeza no son botones aleatorios de muerte instantánea.</p><p><a href="/Syrolands-Public/es/game-design/combat/armor-and-mitigation.html">Armadura y mitigación</a> define las interacciones de protección y estado. <a href="/Syrolands-Public/es/game-design/combat/stamina-and-reactive-combat.html">Stamina y recuperación</a> define el compromiso y ritmo propuestos. Los disparos apuntados a distancia siguen sin resolverse; la configuración actual de combate cuerpo a cuerpo localizado no establece su soporte.</p><h2 id="quality-and-professions" tabindex="-1">Calidad y profesiones <a class="header-anchor" href="#quality-and-professions" aria-label="Enlace permanente a &quot;Calidad y profesiones&quot;">​</a></h2><p>Las cinco dimensiones canónicas de calidad —Offensive Efficiency, Handling, Precision/Consistency, Integrity y Functional Retention— se definen únicamente en <a href="/Syrolands-Public/es/game-design/items/itemization-and-craft-quality.html#weapon-quality-dimensions">Itemization &amp; Craft Quality</a>. La calidad no convierte un hacha en una lanza ni concede penetración universal. Los rasgos especiales, umbrales y propiedades latentes requieren reglas de interacción explícitas; no sustituyen el trauma residual ×2.</p><p><a href="/Syrolands-Public/es/game-design/professions/blacksmithing.html">Blacksmithing</a> cubre la experiencia propuesta en equipo metálico; <a href="/Syrolands-Public/es/game-design/professions/carpentry.html#bowmaking-and-fletching">Carpentry / Bowmaking</a> cubre la construcción de arcos correspondiente. El mantenimiento apoya la <a href="/Syrolands-Public/es/game-design/equipment-and-loot.html">economía de reemplazo y pérdida significativa</a> aceptada. Los Masterworks no conceden seguro ni conservación permanente.</p><h2 id="related-design" tabindex="-1">Diseño relacionado <a class="header-anchor" href="#related-design" aria-label="Enlace permanente a &quot;Diseño relacionado&quot;">​</a></h2><p><a href="/Syrolands-Public/es/game-design/combat/status-and-open-questions.html">Estado y decisiones sin resolver</a></p><h2 id="batch-06-numeric-test-scope" tabindex="-1">Alcance numérico de prueba de Batch 06 <a class="header-anchor" href="#batch-06-numeric-test-scope" aria-label="Enlace permanente a &quot;Alcance numérico de prueba de Batch 06&quot;">​</a></h2><p>El <a href="/Syrolands-Public/es/game-design/combat/numeric-prototype.html">perfil de tres armas</a> asigna valores de prueba con estado Experimental a Longsword, Spear y War Hammer. Sus reglas de fases, recursos, cadencia, Flow, Familiarity marcial y preparación solo se aplican a esa prueba futura. Los ejemplos anteriores siguen siendo alternativas históricas fuera de este perfil; de ello no se deriva equilibrio definitivo, implementación de juego ni asignación numérica de hechizos.</p>',17)])])}const g=e(t,[["render",s]]);export{u as __pageData,g as default};
